  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return seedState();
      const parsed = JSON.parse(raw);
      const seeded = seedState();
      const shouldPurgeOperationalRecords = !parsed.appSettings || parsed.appSettings.operationalResetVersion !== OPERATIONAL_RESET_VERSION;
      const loaded = {
        ...seeded,
        ...parsed,
        users: parsed.users || seeded.users,
        clients: parsed.clients || seeded.clients,
        products: parsed.products || seeded.products,
        vehicles: parsed.vehicles || seeded.vehicles,
        providers: parsed.providers || seeded.providers,
        prices: parsed.prices || seeded.prices,
        orders: parsed.orders || [],
        exampleOrders: parsed.exampleOrders || seeded.exampleOrders || [],
        remitos: parsed.remitos || [],
        saldos: parsed.saldos || [],
        purchases: parsed.purchases || [],
        providerLedger: parsed.providerLedger || [],
        providerPayments: parsed.providerPayments || [],
        clientTransfers: parsed.clientTransfers || [],
        billingLog: parsed.billingLog || [],
        costRelations: parsed.costRelations || [],
        productRelations: parsed.productRelations || [],
        vendorLedger: parsed.vendorLedger || [],
        productAliases: parsed.productAliases || [],
        clientProductAliases: parsed.clientProductAliases || [],
        quantityAliases: mergeQuantityAliases(parsed.quantityAliases || []),
        clientQuantityAliases: parsed.clientQuantityAliases || [],
        attendance: parsed.attendance || [],
        cashClosings: parsed.cashClosings || [],
        marginSections: (Array.isArray(parsed.marginSections) && parsed.marginSections.length) ? parsed.marginSections : seeded.marginSections,
        priceAutoLog: parsed.priceAutoLog || [],
        priceAutoSchedule: parsed.priceAutoSchedule || [],
        employeePayments: parsed.employeePayments || [],
        employeeReimbursements: parsed.employeeReimbursements || [],
        performanceAdjustments: parsed.performanceAdjustments || [],
        appSettings: { ...defaultAppSettings(), ...(parsed.appSettings || {}) },
        cashBoxes: mergeCashBoxes(parsed.cashBoxes || []),
        caja: parsed.caja || [],
        payments: parsed.payments || [],
        preferences: parsed.preferences || [],
        stockMovements: parsed.stockMovements || []
      };
      const normalized = normalizeLoadedState(loaded, seeded);
      if (shouldPurgeOperationalRecords) {
        purgeOperationalRecords(normalized);
        normalized.appSettings.operationalResetVersion = OPERATIONAL_RESET_VERSION;
        writeLocalStateSnapshot(normalized, "No se pudo persistir el estado normalizado en localStorage.");
      }
      return normalized;
    } catch (error) {
      console.warn("No se pudo cargar localStorage, usando datos iniciales.", error);
      return seedState();
    }
  }

  function normalizeLoadedState(loaded, seeded) {
    const users = Array.isArray(loaded.users) ? loaded.users.slice() : [];
    seeded.users.forEach((defaultUser) => {
      const existing = users.find((user) => user.username === defaultUser.username || user.id === defaultUser.id);
      if (existing) {
        Object.assign(existing, {
          password: existing.password || defaultUser.password,
          role: existing.role || defaultUser.role,
          clientId: existing.clientId || defaultUser.clientId,
          isActive: existing.isActive !== false
        });
      } else {
        users.push({ ...defaultUser });
      }
    });
    users.forEach((user) => {
      if (user.role === "manager" && !user.password) user.password = "gerente123";
      if (user.role === "admin" && !user.password) user.password = "admin123";
      if (user.role === "employee" && !user.password) user.password = "empleado123";
      if (user.role === "customer" && !user.password) user.password = "cliente123";
      if (user.role === "example" && !user.password) user.password = "ejemplo123";
      user.email = user.email || "";
      user.phone = user.phone || "";
      if (user.role === "employee" && !user.hourlyRate) user.hourlyRate = 2500;
      if (user.role === "employee" && !user.overtimeRate) user.overtimeRate = Math.round(Number(user.hourlyRate || 2500) * 1.5);
      if (user.role === "employee" && !user.overtimeStart) user.overtimeStart = "14:00";
      if (user.role === "employee" && !user.shiftStart) user.shiftStart = "05:45";
      if (user.role === "employee" && !user.shiftEnd) user.shiftEnd = "13:45";
      if (isClientLikeRole(user.role) && !Array.isArray(user.linkedClientIds)) user.linkedClientIds = [user.clientId].filter(Boolean);
    });
    const defaultExample = seeded.users.find((user) => user.username === "ejemplo");
    let exampleUser = users.find((user) => user.id === (defaultExample && defaultExample.id) || user.username === "ejemplo" || (user.role === "example" && user.clientId === "DEMO"));
    if (defaultExample && exampleUser) {
      Object.assign(exampleUser, {
        id: exampleUser.id || defaultExample.id,
        name: exampleUser.name || defaultExample.name,
        username: "ejemplo",
        password: "ejemplo123",
        role: "example",
        clientId: "DEMO",
        linkedClientIds: ["DEMO"],
        email: exampleUser.email || defaultExample.email,
        phone: exampleUser.phone || "",
        isActive: true
      });
    } else if (defaultExample) {
      users.push({ ...defaultExample });
    }
    const clients = (Array.isArray(loaded.clients) ? loaded.clients : []).map((client) => ({
      email: "",
      billingEmail: "",
      needsInvoice: false,
      cuit: "",
      legalName: "",
      invoiceType: "Factura B",
      invoiceFrequency: "mensual",
      priceAdjustmentPct: client.priceTier === "preferencial" ? -5 : 0,
      zone: "",
      openingTime: "",
      maxDeliveryTime: "",
      ...client
    }));
    clients.forEach((client) => {
      if (client.paymentType === "fiado") client.paymentType = "cuenta_corriente";
      if (!client.invoiceType || (!client.needsInvoice && client.priceTier !== "con_factura")) client.invoiceType = "Sin Factura";
    });
    const products = (Array.isArray(loaded.products) ? loaded.products : []).map((product) => ({
      ivaType: "10.5",
      imageSeed: product.category + "-" + String(product.name || "").slice(0, 2).toUpperCase(),
      imageUrl: "",
      imageData: "",
      allowUnitWeight: false,
      showInVehicleTotals: true,
      ...product
    }));
    Object.keys(loaded.prices || {}).forEach((productId) => {
      const product = products.find((item) => item.id === productId);
      const rec = loaded.prices[productId];
      if (!rec) return;
      rec.marketPrice = Number(rec.marketPrice || 0);
      rec.marginPct = Number.isFinite(Number(rec.marginPct)) ? Number(rec.marginPct) : calcMargin(rec.cost || (product && product.baseCost), rec.price || (product && product.salePrice));
    });
    loaded.appSettings.productCategories = normalizeProductCategories([
      ...(loaded.appSettings.productCategories || []),
      ...products.map((product) => product.category || "OTROS")
    ]);
    loaded.appSettings.unitTypes = normalizeUnitTypes([
      ...(loaded.appSettings.unitTypes || []),
      ...products.map((product) => ({ name: product.unitType || "", wholesale: false }))
    ]);
    const providers = Array.isArray(loaded.providers) ? loaded.providers.slice() : [];
    seeded.providers.forEach((defaultProvider) => {
      const existing = providers.find((provider) => provider.id === defaultProvider.id || provider.name === defaultProvider.name);
      if (existing && (!Array.isArray(existing.productsSupplied) || existing.productsSupplied.length === 0)) {
        existing.productsSupplied = defaultProvider.productsSupplied.slice();
      }
    });
    const saldos = reconcileOrderSaldos({ ...loaded, clients, products });
    const cashBoxes = mergeCashBoxes(loaded.cashBoxes || []);
    const caja = (Array.isArray(loaded.caja) ? loaded.caja : []).map((entry) => ({
      ...entry,
      cashBoxId: entry.cashBoxId || inferCashBoxId(entry)
    }));
    const exampleOrders = Array.isArray(loaded.exampleOrders) && loaded.exampleOrders.length ? loaded.exampleOrders : defaultExampleOrders(products);
    const employeeReimbursements = Array.isArray(loaded.employeeReimbursements) ? loaded.employeeReimbursements : [];
    const clientTransfers = Array.isArray(loaded.clientTransfers) ? loaded.clientTransfers : [];
    const deletedOrders = Array.isArray(loaded.deletedOrders) ? loaded.deletedOrders.slice() : [];
    const normalized = { ...loaded, users, clients, products, providers, saldos, caja, cashBoxes, exampleOrders, employeeReimbursements, clientTransfers, deletedOrders, appSettings: { ...defaultAppSettings(), ...(loaded.appSettings || {}) } };
    normalized.preferences = reconcileClientProductPreferences(normalized);
    ensureUserCashBoxes(normalized);
    return normalized;
  }

  function orderPreferenceKey(order) {
    const date = String(order && order.date || "").slice(0, 10);
    return String(order && (order.createdAt || order.updatedAt || date || order.id) || "");
  }

  function reconcileClientProductPreferences(source) {
    const existing = Array.isArray(source.preferences) ? source.preferences.slice() : [];
    const byKey = new Map();
    const derivedCounts = new Map();
    existing.forEach((pref) => {
      if (!pref || !pref.clientId || !pref.productId) return;
      byKey.set(pref.clientId + "|" + pref.productId, { ...pref });
    });
    (Array.isArray(source.orders) ? source.orders : [])
      .filter((order) => order && order.clientId && !["cancelado", "anulado"].includes(order.status))
      .forEach((order) => {
        const orderKey = orderPreferenceKey(order);
        const orderedAt = order.createdAt || order.updatedAt || (order.date ? String(order.date).slice(0, 10) + "T00:00:00.000Z" : orderKey);
        (Array.isArray(order.items) ? order.items : []).forEach((item) => {
          if (!item || !item.productId) return;
          const key = order.clientId + "|" + item.productId;
          const purchaseCount = Number(derivedCounts.get(key) || 0) + 1;
          derivedCounts.set(key, purchaseCount);
          const pref = byKey.get(key) || {
            clientId: order.clientId,
            productId: item.productId,
            preferredUnitType: item.unitType || "",
            lastQuantity: 0,
            firstOrderedAt: orderedAt,
            lastOrderedAt: "",
            lastOrderKey: "",
            purchaseCount: 0
          };
          const previousKey = getPreferenceOrderKey(pref);
          pref.firstOrderedAt = pref.firstOrderedAt || orderedAt;
          pref.purchaseCount = purchaseCount;
          if (!previousKey || orderKey >= previousKey) {
            pref.preferredUnitType = item.unitType || pref.preferredUnitType || "";
            pref.lastQuantity = Number(item.quantity || 0);
            pref.lastOrderedAt = orderedAt;
            pref.lastOrderKey = orderKey;
          }
          byKey.set(key, pref);
        });
      });
    return Array.from(byKey.values());
  }

  function defaultAppSettings() {
    return {
      remitoTotalStyle: "box",
      sidebarOrder: [],
      productCategories: CATEGORIES.slice(),
      unitTypes: DEFAULT_UNIT_TYPES.slice(),
      operationalResetVersion: OPERATIONAL_RESET_VERSION,
      priceAuto: defaultPriceAuto()
    };
  }

  function purgeOperationalRecords(targetState) {
    Object.assign(targetState, {
      orders: [],
      remitos: [],
      saldos: [],
      purchases: [],
      costRelations: [],
      vendorLedger: [],
      providerLedger: [],
      providerPayments: [],
      clientTransfers: [],
      replacements: [],
      billingLog: [],
      attendance: [],
      employeePayments: [],
      employeeReimbursements: [],
      performanceAdjustments: [],
      caja: [],
      payments: [],
      preferences: []
    });
    targetState.exampleOrders = defaultExampleOrders(targetState.products || []);
  }

  function defaultCashBoxes() {
    return [
      { id: "cash-general", name: "General", isActive: true, visibleToAdmin: true, notes: "Caja general" },
      { id: "cash-banco", name: "Banco", isActive: true, visibleToAdmin: true, notes: "Transferencias y cheques" }
    ];
  }

  function demoClient() {
    return {
      id: "DEMO",
      name: "Cliente Ejemplo",
      address: "Direccion de ejemplo 123",
      phone: "0000-0000",
      email: "ejemplo@parecarrito.com",
      billingEmail: "facturacion.ejemplo@parecarrito.com",
      contactName: "Contacto Ejemplo",
      paymentType: "cuenta_corriente",
      priceTier: "general",
      priceAdjustmentPct: 0,
      needsInvoice: false,
      cuit: "30-00000000-0",
      legalName: "Cliente Ejemplo SAS",
      invoiceType: "Sin Factura",
      invoiceFrequency: "mensual",
      vehicleId: "Kangoo1",
      isActive: true,
      notes: "Datos ficticios para demostracion."
    };
  }

  function defaultExampleOrders(products) {
    const sampleProducts = (products || []).slice(0, 4);
    const dates = [todayISO(), addDaysISO(todayISO(), -1)];
    return dates.map((date, orderIndex) => {
      const items = sampleProducts.slice(orderIndex, orderIndex + 3).map((product, index) => {
        const quantity = index + 1;
        const unitPrice = Number((product && product.salePrice) || getProductPrice(product && product.id) || 0);
        return {
          id: nextItemId(),
          productId: product.id,
          productName: product.name,
          unitType: product.unitType,
          quantity,
          unitPrice,
          subtotal: quantity * unitPrice,
          ivaAmount: 0,
          totalWithIva: quantity * unitPrice,
          note: index === 0 ? "Nota de ejemplo" : ""
        };
      });
      const subtotalAmount = items.reduce((sum, item) => sum + item.subtotal, 0);
      return {
        id: "EJ-" + String(orderIndex + 1).padStart(3, "0"),
        userId: "USR-004",
        exampleOnly: true,
        date,
        clientId: "DEMO",
        deliveryVehicleId: "Kangoo1",
        status: orderIndex === 0 ? "pendiente" : "entregado",
        items,
        subtotalAmount,
        ivaAmount: 0,
        totalAmount: subtotalAmount,
        paymentReceived: 0,
        paymentStatus: "pending",
        remitoPrinted: false,
        notes: "Pedido ficticio de ejemplo.",
        createdAt: date + "T08:00:00.000Z"
      };
    });
  }

  function mergeCashBoxes(existing) {
    const boxes = (Array.isArray(existing) ? existing.slice() : []).filter((box) => !isDeprecatedCashBox(box));
    defaultCashBoxes().forEach((box) => {
      const current = boxes.find((item) => item.id === box.id);
      if (current) Object.assign(current, { ...box, ...current });
      else boxes.push({ ...box });
    });
    return boxes.map((box) => ({
      id: box.id,
      name: box.name || box.id,
      isActive: box.isActive !== false,
      visibleToAdmin: box.visibleToAdmin !== false,
      notes: box.notes || ""
    }));
  }

  function isDeprecatedCashBox(box) {
    const id = normalizeText(box && box.id);
    const name = normalizeText(box && box.name);
    return id === "cash-proveedores" || id === "cash-efectivo" || id === "cash-empleados" || name === "proveedores" || name === "efectivo";
  }

  function ensureUserCashBoxes(targetState) {
    targetState = targetState || state;
    targetState.cashBoxes = targetState.cashBoxes || [];
    (targetState.users || []).forEach((user) => {
      if (!["manager", "admin", "employee"].includes(user.role)) return;
      const id = getUserCashBoxId(user.id);
      const defaultName = "Efectivo - " + user.name;
      const existing = targetState.cashBoxes.find((box) => box.id === id);
      if (!existing) {
        targetState.cashBoxes.push({
          id,
          name: defaultName,
          isActive: true,
          visibleToAdmin: true,
          userId: user.id,
          notes: "Caja efectivo del usuario"
        });
      } else {
        const expectedPrefix = "Efectivo - ";
        if (!existing.name || (String(existing.name).startsWith(expectedPrefix) && existing.name !== defaultName)) {
          existing.name = defaultName;
        }
        if (existing.userId !== user.id) existing.userId = user.id;
      }
    });
  }

  function mergeQuantityAliases(existing) {
    const aliases = Array.isArray(existing) ? existing.slice() : [];
    DEFAULT_QUANTITY_ALIASES.forEach((defaultAlias) => {
      const key = normalizeAliasKey(defaultAlias.alias);
      if (!aliases.some((alias) => normalizeAliasKey(alias.alias) === key)) {
        aliases.push({ ...defaultAlias });
      }
    });
    return aliases.map((alias) => ({ alias: alias.alias, quantity: Number(alias.quantity || 0) })).filter((alias) => alias.alias && alias.quantity > 0);
  }

  function writeLocalStateSnapshot(data, warningMessage) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      return true;
    } catch (error) {
      console.warn(warningMessage || "No se pudo guardar el estado completo en localStorage.", error);
      return false;
    }
  }

  function localPersistRole() {
    return !!(currentUser && ["manager", "admin"].includes(currentUser.role));
  }
  function saveState() {
    if (localPersistRole()) writeLocalStateSnapshot(state, "No se pudo guardar el estado completo en localStorage; se intentara sincronizar con el servidor.");
    const config = getCloudSyncConfig();
    if (canWritePatchCloudSync() && cloudSyncReady(config) && config.auto !== false) {
      if (!queueCurrentStatePatch()) scheduleCloudPush();
      else schedulePatchFlush();
    }
  }

  function backupLocalState(label) {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      const backups = JSON.parse(localStorage.getItem("lpc_erp_local_backups_v1") || "[]");
      backups.unshift({
        at: new Date().toISOString(),
        label: label || "auto",
        stateRaw: raw
      });
      while (backups.length > 10) backups.pop();
      localStorage.setItem("lpc_erp_local_backups_v1", JSON.stringify(backups));
    } catch (e) {
      console.warn("No se pudo crear backup local:", e);
    }
  }

  function listLocalBackups() {
    try {
      return JSON.parse(localStorage.getItem("lpc_erp_local_backups_v1") || "[]");
    } catch {
      return [];
    }
  }

  function restoreLocalBackup(index) {
    const backups = listLocalBackups();
    const backup = backups[index];
    if (!backup || !backup.stateRaw) return false;
    try {
      const parsed = JSON.parse(backup.stateRaw);
      if (!parsed.clients || !parsed.products) return false;
      state = normalizeLoadedState({ ...seedState(), ...parsed }, seedState());
      writeLocalStateSnapshot(parsed, "No se pudo persistir el backup restaurado en localStorage.");
      currentUser = loadCurrentUser();
      render();
      return true;
    } catch (e) {
      console.warn("No se pudo restaurar backup:", e);
      return false;
    }
  }

  const SYNC_KEY = "lpc_cloud_sync_v1";
  const PATCH_QUEUE_KEY = "lpc_offline_patch_queue_v1";
  const PATCH_ARRAY_KEYS = [
    "orders", "deletedOrders", "exampleOrders", "remitos", "saldos", "purchases", "payments", "caja", "replacements",
    "providerLedger", "providerPayments", "clientTransfers", "vendorLedger",
    "attendance", "employeePayments", "employeeReimbursements", "performanceAdjustments",
    "clients", "products", "providers", "vehicles", "users", "cashBoxes",
    "preferences", "productAliases", "clientProductAliases", "quantityAliases", "clientQuantityAliases",
    "costRelations", "productRelations", "billingLog", "stockMovements", "cashClosings", "marginSections", "priceAutoLog", "priceAutoSchedule",
    "holidays"
  ];
  const PATCH_OBJECT_KEYS = ["prices", "appSettings"];
  const HISTORY_STATE_KEYS = ["productListPriceHistory", "productSalesQuantityHistory", "productPurchaseHistory"];
  let cloudPushTimer = null;

  function stripHistoryForSync(data) {
    const clean = { ...(data || {}) };
    HISTORY_STATE_KEYS.forEach((key) => delete clean[key]);
    return clean;
  }

  function cloneSyncState(data) {
    return JSON.parse(JSON.stringify(stripHistoryForSync(data || {})));
  }

  function patchKeyForItem(key, item) {
    if (!item) return "";
    if (key === "preferences") return String(item.clientId || "") + "|" + String(item.productId || "");
    if (key === "productAliases") return String(item.productId || "") + "|" + String(item.alias || "");
    if (key === "clientProductAliases") return String(item.clientId || "") + "|" + String(item.productId || "") + "|" + String(item.alias || "");
    if (key === "quantityAliases") return String(item.alias || "");
    if (key === "clientQuantityAliases") return String(item.clientId || "") + "|" + String(item.alias || "");
    if (key === "costRelations") return item.id || JSON.stringify([item.sourceProductId, item.targetProductId, item.productId]);
    if (key === "productRelations") return item.id || String(item.retailProductId || "") + "|" + String(item.wholesaleProductId || "");
    return String(item.id || "");
  }

  function buildStatePatch(baseData, nextData) {
    const base = stripHistoryForSync(baseData || {});
    const next = stripHistoryForSync(nextData || {});
    const patch = { arrays: {}, objects: {}, scalars: {} };
    PATCH_ARRAY_KEYS.forEach((key) => {
      const baseMap = new Map();
      (Array.isArray(base[key]) ? base[key] : []).forEach((item) => {
        const id = patchKeyForItem(key, item);
        if (id) baseMap.set(id, JSON.stringify(item));
      });
      const nextMap = new Map();
      (Array.isArray(next[key]) ? next[key] : []).forEach((item) => {
        const id = patchKeyForItem(key, item);
        if (id) nextMap.set(id, item);
      });
      const upsert = [];
      const deleted = [];
      nextMap.forEach((item, id) => {
        if (baseMap.get(id) !== JSON.stringify(item)) upsert.push(item);
      });
      baseMap.forEach((_, id) => {
        if (!nextMap.has(id)) deleted.push(id);
      });
      if (upsert.length || deleted.length) patch.arrays[key] = { upsert, delete: deleted };
    });
    PATCH_OBJECT_KEYS.forEach((key) => {
      const changes = {};
      const baseObj = base[key] || {};
      const nextObj = next[key] || {};
      Object.keys(nextObj).forEach((entryKey) => {
        if (JSON.stringify(baseObj[entryKey]) !== JSON.stringify(nextObj[entryKey])) changes[entryKey] = nextObj[entryKey];
      });
      if (Object.keys(changes).length) patch.objects[key] = changes;
    });
    Object.keys(next).forEach((key) => {
      if (PATCH_ARRAY_KEYS.includes(key) || PATCH_OBJECT_KEYS.includes(key) || HISTORY_STATE_KEYS.includes(key)) return;
      if (JSON.stringify(base[key]) !== JSON.stringify(next[key])) patch.scalars[key] = next[key];
    });
    return patch;
  }

  function patchHasChanges(patch) {
    return !!(patch && (
      Object.keys(patch.arrays || {}).length ||
      Object.keys(patch.objects || {}).length ||
      Object.keys(patch.scalars || {}).length
    ));
  }

  function pendingSyncCount() {
    let n = 0;
    try { n += (loadPatchQueue() || []).length; } catch (e) { /* ignore */ }
    try { n += (loadClientWriteQueue() || []).length; } catch (e) { /* ignore */ }
    return n;
  }
  function loadPatchQueue() {
    try {
      return JSON.parse(localStorage.getItem(PATCH_QUEUE_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function savePatchQueue(queue) {
    try {
      localStorage.setItem(PATCH_QUEUE_KEY, JSON.stringify(queue || []));
    } catch (error) {
      console.warn("No se pudo guardar la cola offline.", error);
    }
  }

  function clearPatchQueueAfterCloudPull(reason) {
    const count = loadPatchQueue().length;
    if (!count) return 0;
    savePatchQueue([]);
    pendingPatchBaseState = null;
    pendingPatchBaseUpdatedAt = "";
    ui.syncStatus = reason || "Datos descargados; cambios pendientes anteriores descartados";
    return count;
  }

  function queueCurrentStatePatch() {
    const config = getCloudSyncConfig();
    if (!config.lastSync || !lastSyncedState) return false;
    if (!pendingPatchBaseState) {
      const existing = loadPatchQueue()[0];
      pendingPatchBaseState = lastSyncedState;
      pendingPatchBaseUpdatedAt = existing ? existing.baseUpdatedAt : config.lastSync;
    }
    const patch = buildStatePatch(pendingPatchBaseState, state);
    if (!patchHasChanges(patch)) return false;
    savePatchQueue([{
      operationId: "op-" + Date.now() + "-" + Math.random().toString(36).slice(2, 10),
      operationType: "patch",
      baseUpdatedAt: pendingPatchBaseUpdatedAt || config.lastSync,
      patch,
      createdAt: new Date().toISOString()
    }]);
    ui.syncStatus = navigator.onLine === false ? "Cambios pendientes sin conexión" : "Cambios pendientes por sincronizar";
    return true;
  }

  function getCloudSyncConfig() {
    try {
      return JSON.parse(localStorage.getItem(SYNC_KEY) || "{}") || {};
    } catch {
      return {};
    }
  }

  function saveCloudSyncConfig(config) {
    try {
      localStorage.setItem(SYNC_KEY, JSON.stringify(config || {}));
    } catch (error) {
      console.warn("No se pudo guardar la configuración de sincronización local.", error);
    }
  }

  function cloudSyncReady(config) {
    return !!(config && config.url && (config.token || (config.username && config.password)));
  }

  function configAutoEnabled(config) {
    return !config || config.auto !== false;
  }

  function canReadCloudState() {
    return !currentUser || !isClientLikeRole(currentUser.role);
  }

  function canWriteFullCloudSync() {
    return !currentUser || ["manager", "admin", "contador"].includes(currentUser.role);
  }

  function canWritePatchCloudSync() {
    // proveedor incluido: carga compras/precios de sus productos y debe sincronizar al servidor
    // (antes solo persistia en localStorage y no se veia en el resto del sistema).
    return !currentUser || ["manager", "admin", "employee", "contador", "proveedor"].includes(currentUser.role);
  }

  function canUseFullCloudSync() {
    return canWriteFullCloudSync();
  }

  function cloudBaseUrl(config) {
    return String(config.url || "").trim().replace(/\/+$/, "");
  }

  async function cloudLogin(config) {
    const response = await fetch(cloudBaseUrl(config) + "/auth/login", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ username: config.username, password: config.password })
    });
    if (!response.ok) {
      let detail = "";
      try {
        detail = (await response.json()).error || "";
      } catch {}
      throw new Error(detail || "no se pudo iniciar sesión en el servidor (HTTP " + response.status + ")");
    }
    const payload = await response.json();
    config.jwt = payload.token;
    saveCloudSyncConfig(config);
    return payload;
  }

  async function cloudRequest(config, path, options, retried) {
    const useJwt = !!config.username;
    if (useJwt && !config.jwt) await cloudLogin(config);
    const response = await fetch(cloudBaseUrl(config) + path, {
      ...(options || {}),
      headers: {
        "content-type": "application/json",
        authorization: "Bearer " + (useJwt ? config.jwt : config.token),
        ...((options && options.headers) || {})
      }
    });
    if (response.status === 401 && useJwt && !retried) {
      await cloudLogin(config);
      return cloudRequest(config, path, options, true);
    }
    return response;
  }

  function scheduleCloudPush() {
    const config = getCloudSyncConfig();
    if (!canWriteFullCloudSync() || !cloudSyncReady(config) || config.auto === false) return;
    clearTimeout(cloudPushTimer);
    cloudPushTimer = setTimeout(() => {
      cloudPushTimer = null;
      cloudPush(false);
    }, 500);
  }

  function schedulePatchFlush(delay) {
    const config = getCloudSyncConfig();
    if (!canWritePatchCloudSync() || !cloudSyncReady(config) || config.auto === false) return;
    clearTimeout(cloudPushTimer);
    cloudPushTimer = setTimeout(() => {
      cloudPushTimer = null;
      flushPatchQueue(false);
    }, delay || 500);
  }

  async function flushPatchQueue(manual, resolvingConflict) {
    const config = getCloudSyncConfig();
    if (!canWritePatchCloudSync()) {
      if (manual) alert("Este rol no usa sincronizacion completa. Sus acciones permitidas se envian por canales especificos.");
      return true;
    }
    const queue = loadPatchQueue();
    if (!queue.length) {
      if (manual) alert("No hay cambios pendientes.");
      return true;
    }
    if (!cloudSyncReady(config)) {
      if (manual) alert("Configure la sincronización antes de subir cambios.");
      return false;
    }
    if (navigator.onLine === false) {
      ui.syncStatus = queue.length + " cambio(s) pendiente(s) sin conexión";
      schedulePatchFlush(5000);
      return false;
    }
    const op = queue[0];
    try {
      ui.syncStatus = "Sincronizando cambios pendientes...";
      // keepalive: le pide al navegador que COMPLETE el envio aunque la pagina se congele,
      // se mande a segundo plano o se cierre (caso tipico: el empleado guarda y bloquea el
      // celular al instante). El estandar limita keepalive a 64KB de cuerpo, asi que solo se
      // usa cuando el patch entra en ese limite; si es mas grande, va como envio normal.
      const opBody = JSON.stringify(op);
      const response = await cloudRequest(config, "/state/patch", {
        method: "POST",
        body: opBody,
        ...(opBody.length < 60000 ? { keepalive: true } : {})
      });
      if (response.status === 409) {
        const merged = !resolvingConflict && await mergePendingPatchConflictWithRemote(config, manual);
        if (merged) return flushPatchQueue(manual, true);
        const detail = await readCloudErrorDetail(response);
        config.lastError = "Conflicto al sincronizar cambio pendiente" + detail + ". Se conservo la informacion local y se reintentara la sincronizacion.";
        saveCloudSyncConfig(config);
        ui.syncStatus = "Conflicto de sincronización";
        ui.syncStatus = "Cambios pendientes por sincronizar";
        if (manual) alert(config.lastError);
        schedulePatchFlush(6000);
        return false;
      }
      if (!response.ok) throw new Error("HTTP " + response.status + (await readCloudErrorDetail(response)));
      const payload = await response.json();
      savePatchQueue([]);
      pendingPatchBaseState = null;
      pendingPatchBaseUpdatedAt = "";
      config.lastSync = payload.updatedAt || new Date().toISOString();
      config.lastError = "";
      saveCloudSyncConfig(config);
      lastSyncedState = cloneSyncState(state);
      ui.syncStatus = "Guardado";
      if (manual) alert("Cambios pendientes sincronizados.");
      return true;
    } catch (error) {
      config.lastError = "Subida pendiente fallida " + formatTimestampShort(new Date().toISOString()) + ": " + error.message;
      saveCloudSyncConfig(config);
      ui.syncStatus = "Sincronización pendiente";
      console.warn("Sincronización pendiente:", error.message);
      schedulePatchFlush(5000);
      if (manual) alert("No se pudo sincronizar todavía: " + error.message);
      return false;
    }
  }

  async function mergePendingPatchConflictWithRemote(config, manual) {
    try {
      const remoteResponse = await cloudRequest(config, "/state", { method: "GET" });
      if (!remoteResponse.ok) return false;
      const remotePayload = await remoteResponse.json();
      if (!remotePayload || typeof remotePayload.data !== "object") return false;
      backupLocalState("antes de fusion por conflicto de sincronizacion");
      const remoteState = normalizeLoadedState({ ...seedState(), ...remotePayload.data }, seedState());
      state = normalizeLoadedState({ ...seedState(), ...mergeCloudStates(remoteState, state) }, seedState());
      writeLocalStateSnapshot(state, "No se pudo guardar la fusion local contra la nube.");
      savePatchQueue([]);
      config.lastSync = String(remotePayload.updatedAt || new Date().toISOString());
      config.lastError = "";
      saveCloudSyncConfig(config);
      lastSyncedState = cloneSyncState(remoteState);
      pendingPatchBaseState = lastSyncedState;
      pendingPatchBaseUpdatedAt = config.lastSync;
      const queued = queueCurrentStatePatch();
      if (!queued) {
        pendingPatchBaseState = null;
        pendingPatchBaseUpdatedAt = "";
        ui.syncStatus = "Guardado";
        return true;
      }
      ui.syncStatus = "Cambios locales fusionados; sincronizando...";
      ui.syncWarning = "Se fusiono la version del servidor con los cambios locales de esta computadora. Se reintentara la subida sin sobrescribir lo local.";
      if (manual) alert("Se fusiono la version del servidor con los cambios locales de esta computadora. Ahora se reintentara subir la informacion local.");
      return true;
    } catch (error) {
      console.warn("No se pudo fusionar conflicto pendiente:", error.message);
      return false;
    }
  }

  function flushCloudPush() {
    if (cloudPushTimer) {
      clearTimeout(cloudPushTimer);
      cloudPushTimer = null;
    }
    const config = getCloudSyncConfig();
    if (!canWriteFullCloudSync() || !cloudSyncReady(config) || config.auto === false) return false;
    try {
      const xhr = new XMLHttpRequest();
      xhr.open("PUT", cloudBaseUrl(config) + "/state", false);
      xhr.setRequestHeader("content-type", "application/json");
      xhr.setRequestHeader("authorization", "Bearer " + (config.username ? config.jwt : config.token));
      xhr.send(JSON.stringify({ data: state, baseUpdatedAt: config.lastSync || null }));
      if (xhr.status >= 200 && xhr.status < 300) {
        try {
          const payload = JSON.parse(xhr.responseText);
          config.lastSync = payload.updatedAt || new Date().toISOString();
          config.lastError = "";
          saveCloudSyncConfig(config);
          return true;
        } catch {
          return false;
        }
      }
      if (xhr.status === 401 && config.username) {
        // Token expirado; dejar que el push async normal maneje el re-login
        scheduleCloudPush();
      }
      return false;
    } catch (error) {
      console.warn("No se pudo enviar el push sincronico:", error);
      return false;
    }
  }

  let cloudPollTimer = null;

  function startCloudAutoSync() {
    clearInterval(cloudPollTimer);
    const config = getCloudSyncConfig();
    if (!canReadCloudState() || !cloudSyncReady(config) || config.auto === false) return;
    cloudPollTimer = setInterval(() => {
      cloudPull(false);
    }, 25000);
  }

  async function readCloudErrorDetail(response) {
    try {
      const payload = await response.json();
      return payload && payload.error ? " - " + payload.error : "";
    } catch {
      return "";
    }
  }

  async function cloudPush(manual, isRetry) {
    const config = getCloudSyncConfig();
    if (loadPatchQueue().length) {
      const ok = await flushPatchQueue(manual);
      if (ok || manual) return;
    }
    if (!canWriteFullCloudSync()) {
      if (manual) alert(currentUser && currentUser.role === "employee" ? "El rol Empleado sincroniza cambios mediante operaciones chicas. No sube el estado completo del sistema." : "Este rol no puede subir el estado completo. Use las acciones permitidas.");
      return;
    }
    if (!cloudSyncReady(config)) {
      if (manual) alert("Configure la URL y el token del backend en este panel.");
      return;
    }
    try {
      if (!isRetry && config.lastSync) {
        try {
          const peek = await cloudRequest(config, "/state", { method: "GET" });
          if (peek.ok) {
            const remoteInfo = await peek.json();
            const remoteUpdated = String(remoteInfo.updatedAt || "");
            if (remoteUpdated && remoteUpdated !== config.lastSync && localStateIsNewerOrRicher(remoteInfo.data || {}, state)) {
              const local = stateOperationalCounts(state);
              const remote = stateOperationalCounts(remoteInfo.data || {});
              const details = Object.keys(local).filter((k) => local[k] !== remote[k]).map((k) => `${k}: local ${local[k]} vs nube ${remote[k]}`).join(", ");
              const msg = `No se puede subir: el servidor tiene datos mas recientes (${details}). Descargue primero con "Descargar datos ahora".`;
              config.lastError = msg;
              saveCloudSyncConfig(config);
              if (manual) alert(msg);
              return;
            }
          }
        } catch (peekErr) {
          console.warn("No se pudo verificar estado remoto antes de subir:", peekErr.message);
        }
      }
      const response = await cloudRequest(config, "/state", {
        method: "PUT",
        body: JSON.stringify({ data: state, baseUpdatedAt: config.lastSync || null })
      });
      if (response.status === 409 && !isRetry) {
        // Otro dispositivo subio datos mas nuevos: descargar, combinar y reintentar.
        const remoteResponse = await cloudRequest(config, "/state", { method: "GET" });
        if (remoteResponse.ok) {
          const remote = await remoteResponse.json();
          const merged = mergeCloudStates(remote.data, state);
          state = normalizeLoadedState({ ...seedState(), ...merged }, seedState());
          writeLocalStateSnapshot(state, "No se pudo guardar el estado combinado en localStorage.");
          config.lastSync = String(remote.updatedAt || "");
          saveCloudSyncConfig(config);
          currentUser = loadCurrentUser();
          render();
          return cloudPush(manual, true);
        }
      }
      if (!response.ok) throw new Error("HTTP " + response.status + (await readCloudErrorDetail(response)));
      const payload = await response.json();
      config.lastSync = payload.updatedAt || new Date().toISOString();
      config.lastError = "";
      saveCloudSyncConfig(config);
      lastSyncedState = cloneSyncState(state);
      if (manual) {
        alert("Datos subidos a la nube correctamente.");
        render();
      }
    } catch (error) {
      config.lastError = "Subida fallida " + formatTimestampShort(new Date().toISOString()) + ": " + error.message;
      saveCloudSyncConfig(config);
      console.warn("Sincronización: " + error.message);
      if (manual) alert("No se pudo subir a la nube: " + error.message);
    }
  }

  async function syncClientTransferToCloud(transfer) {
    const config = getCloudSyncConfig();
    if (!cloudSyncReady(config)) throw new Error("sin conexión configurada");
    if (navigator.onLine === false) throw new Error("sin conexión");
    try {
      const response = await cloudRequest(config, "/transfers", {
        method: "POST",
        body: JSON.stringify({ transfer })
      });
      if (!response.ok) throw new Error("HTTP " + response.status + (await readCloudErrorDetail(response)));
    } catch (error) {
      console.warn("Sincronización de transferencia fallida:", error.message);
      throw error;
    }
  }

  const CLIENT_WRITE_QUEUE_KEY = "lpc_client_write_queue_v1";
  let clientWriteTimer = null;

  function loadClientWriteQueue() {
    try {
      return JSON.parse(localStorage.getItem(CLIENT_WRITE_QUEUE_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function saveClientWriteQueue(queue) {
    try {
      localStorage.setItem(CLIENT_WRITE_QUEUE_KEY, JSON.stringify(queue || []));
    } catch (error) {
      console.warn("No se pudo guardar la cola de cliente.", error);
    }
  }

  function queueClientWrite(type, payload) {
    const queue = loadClientWriteQueue();
    const duplicate = queue.some((op) => op && op.type === type && JSON.stringify(op.payload) === JSON.stringify(payload));
    if (!duplicate) {
      queue.push({
        id: "cw-" + Date.now() + "-" + Math.random().toString(36).slice(2, 10),
        type,
        payload,
        createdAt: new Date().toISOString()
      });
      saveClientWriteQueue(queue);
    }
    scheduleClientWriteFlush();
  }

  function scheduleClientWriteFlush(delay) {
    clearTimeout(clientWriteTimer);
    clientWriteTimer = setTimeout(() => {
      clientWriteTimer = null;
      flushClientWriteQueue(false);
    }, delay || 5000);
  }

  async function sendClientWrite(op) {
    if (!op || op.type === "transfer") return syncClientTransferToCloud(op && op.payload && op.payload.transfer);
    if (op.type === "order") return syncCustomerOrderToCloud(op.payload && op.payload.order);
    return true;
  }

  async function flushClientWriteQueue(manual) {
    if (!currentUser || !isClientLikeRole(currentUser.role)) return true;
    const config = getCloudSyncConfig();
    if (!cloudSyncReady(config) || navigator.onLine === false) {
      if (loadClientWriteQueue().length) scheduleClientWriteFlush(8000);
      return false;
    }
    const queue = loadClientWriteQueue();
    if (!queue.length) return true;
    while (queue.length) {
      try {
        await sendClientWrite(queue[0]);
        queue.shift();
        saveClientWriteQueue(queue);
      } catch (error) {
        console.warn("Escritura de cliente pendiente:", error.message);
        saveClientWriteQueue(queue);
        scheduleClientWriteFlush(8000);
        if (manual) alert("Quedan cambios pendientes por sincronizar: " + error.message);
        return false;
      }
    }
    return true;
  }

  async function syncCustomerOrderToCloud(order) {
    const config = getCloudSyncConfig();
    if (!cloudSyncReady(config)) throw new Error("sin conexión configurada");
    if (navigator.onLine === false) throw new Error("sin conexión");
    const response = await cloudRequest(config, "/orders/customer", {
      method: "POST",
      body: JSON.stringify({ order })
    });
    if (!response.ok) throw new Error("HTTP " + response.status + (await readCloudErrorDetail(response)));
    return response.json();
  }

  function mergeCloudStates(remoteData, localData) {
    const remote = remoteData || {};
    const local = localData || {};
    const merged = { ...remote };
    const unionByKey = (a, b, keyFn) => {
      const map = new Map();
      (Array.isArray(a) ? a : []).forEach((item) => {
        if (item) map.set(keyFn(item), item);
      });
      (Array.isArray(b) ? b : []).forEach((item) => {
        if (item) map.set(keyFn(item), item);
      });
      return Array.from(map.values());
    };
    const unionByKeyPreferNewest = (a, b, keyFn, updatedAtFn) => {
      const map = new Map();
      (Array.isArray(a) ? a : []).forEach((item) => {
        if (item) map.set(keyFn(item), item);
      });
      (Array.isArray(b) ? b : []).forEach((item) => {
        if (!item) return;
        const key = keyFn(item);
        const existing = map.get(key);
        if (!existing) {
          map.set(key, item);
          return;
        }
        const existingTime = new Date(existing[updatedAtFn] || existing.createdAt || 0).getTime();
        const itemTime = new Date(item[updatedAtFn] || item.createdAt || 0).getTime();
        if (itemTime > existingTime) map.set(key, item);
      });
      return Array.from(map.values());
    };
    const byId = (item) => String(item.id);
    merged.orders = unionByKeyPreferNewest(remote.orders, local.orders, byId, "updatedAt");
    merged.deletedOrders = unionByKeyPreferNewest(remote.deletedOrders, local.deletedOrders, byId, "updatedAt");
    if (Array.isArray(merged.orders) && Array.isArray(merged.deletedOrders)) {
      const newestTime = (item) => new Date(item.updatedAt || item.deletedAt || item.createdAt || 0).getTime();
      merged.orders = merged.orders.filter((order) => {
        const del = merged.deletedOrders.find((d) => d.id === order.id);
        if (!del) return true;
        return newestTime(order) >= newestTime(del);
      });
      merged.deletedOrders = merged.deletedOrders.filter((del) => {
        const order = merged.orders.find((o) => o.id === del.id);
        if (!order) return true;
        return newestTime(del) > newestTime(order);
      });
    }
    [
      "exampleOrders", "remitos", "saldos", "payments", "caja", "replacements",
      "providerLedger", "providerPayments", "clientTransfers", "vendorLedger",
      "attendance", "employeePayments", "employeeReimbursements", "performanceAdjustments",
      "stockMovements"
    ].forEach((key) => {
      merged[key] = unionByKey(remote[key], local[key], byId);
    });
    // Entidades que se editan en el lugar (config + compras): ante un mismo id gana la version
    // mas nueva por updatedAt; sin updatedAt gana el REMOTO (el servidor es autoritativo).
    // Antes gana SIEMPRE el local, por lo que un navegador con snapshot viejo (tipico despues de
    // un deploy, cuando todos recargan) revertia proveedores, clientes y productos y los re-pusheaba.
    // Si el estado local es el "seed" (datos de ejemplo con los que viene el sistema, sin datos
    // operativos reales), NO se inyectan esos defaults sobre el servidor: se usa el remoto tal cual.
    // Esto evita que, en una carga fresca (post-deploy, incognito, cache limpio), los clientes/
    // productos/proveedores por defecto reemplacen a los reales.
    const localIsSeed = looksLikeSeedState(local);
    [
      "clients", "products", "providers", "vehicles", "users", "cashBoxes", "purchases"
    ].forEach((key) => {
      merged[key] = localIsSeed
        ? (Array.isArray(remote[key]) ? remote[key].slice() : [])
        : unionByKeyPreferNewest(remote[key], local[key], byId, "updatedAt");
    });
    // prices: merge por producto, gana el rec con updatedAt mas nuevo (remoto en empate o si
    // el local no tiene timestamp). Antes era "local gana siempre", por lo que una copia vieja
    // (tipico el gerente que hace push completo) revertia el precio actualizado por una compra.
    merged.prices = (function () {
      const out = { ...(remote.prices || {}) };
      const loc = local.prices || {};
      Object.keys(loc).forEach((pid) => {
        const r = out[pid];
        const l = loc[pid];
        if (!r) { out[pid] = l; return; }
        const rt = r && r.updatedAt ? Date.parse(r.updatedAt) || 0 : 0;
        const lt = l && l.updatedAt ? Date.parse(l.updatedAt) || 0 : 0;
        out[pid] = lt > rt ? l : r;
      });
      return out;
    })();
    merged.appSettings = { ...(remote.appSettings || {}), ...(local.appSettings || {}) };
    merged.preferences = unionByKey(remote.preferences, local.preferences, (item) => item.clientId + "|" + item.productId);
    merged.productAliases = unionByKey(remote.productAliases, local.productAliases, (item) => item.productId + "|" + String(item.alias));
    merged.clientProductAliases = unionByKey(remote.clientProductAliases, local.clientProductAliases, (item) => item.clientId + "|" + item.productId + "|" + String(item.alias));
    merged.quantityAliases = unionByKey(remote.quantityAliases, local.quantityAliases, (item) => String(item.alias));
    merged.clientQuantityAliases = unionByKey(remote.clientQuantityAliases, local.clientQuantityAliases, (item) => item.clientId + "|" + String(item.alias));
    merged.costRelations = unionByKey(remote.costRelations, local.costRelations, (item) => JSON.stringify([item.sourceProductId, item.targetProductId, item.productId]));
    merged.productRelations = unionByKey(remote.productRelations, local.productRelations, (item) => item.retailProductId + "|" + item.wholesaleProductId);
    merged.billingLog = unionByKey(remote.billingLog, local.billingLog, (item) => String(item.id));
    merged.marginSections = (Array.isArray(local.marginSections) && local.marginSections.length) ? local.marginSections : (remote.marginSections || []);
    merged.priceAutoLog = unionByKey(remote.priceAutoLog, local.priceAutoLog, byId);
    merged.priceAutoSchedule = unionByKey(remote.priceAutoSchedule, local.priceAutoSchedule, (item) => String(item.productId));
    return merged;
  }

  function stateHasOperationalData(data) {
    return [
      "orders", "purchases", "saldos", "caja", "payments", "remitos", "replacements",
      "providerLedger", "providerPayments", "clientTransfers", "attendance",
      "employeePayments", "employeeReimbursements", "billingLog", "vendorLedger"
    ].some((key) => Array.isArray(data[key]) && data[key].length);
  }

  function looksLikeSeedState(data) {
    return !stateHasOperationalData(data);
  }

  function localStateIsRicherThanRemote(localData, remoteData) {
    const count = (arr) => (Array.isArray(arr) ? arr.length : 0);
    return (
      stateHasOperationalData(localData) ||
      count(localData.clients) > count(remoteData.clients) ||
      count(localData.products) > count(remoteData.products) ||
      count(localData.users) > count(remoteData.users) ||
      count(localData.providers) > count(remoteData.providers)
    );
  }

  function stateOperationalCounts(data) {
    return {
      orders: Array.isArray(data.orders) ? data.orders.length : 0,
      clients: Array.isArray(data.clients) ? data.clients.length : 0,
      products: Array.isArray(data.products) ? data.products.length : 0,
      purchases: Array.isArray(data.purchases) ? data.purchases.length : 0,
      payments: Array.isArray(data.payments) ? data.payments.length : 0,
      saldos: Array.isArray(data.saldos) ? data.saldos.length : 0,
      caja: Array.isArray(data.caja) ? data.caja.length : 0
    };
  }

  function localStateIsNewerOrRicher(localData, remoteData) {
    const local = stateOperationalCounts(localData);
    const remote = stateOperationalCounts(remoteData);
    return Object.keys(local).some((key) => local[key] > remote[key]);
  }

  function hasLocalUnsyncedPatchChanges() {
    if (loadPatchQueue().length) return true;
    const config = getCloudSyncConfig();
    if (!config.lastSync || !lastSyncedState) return false;
    try {
      return patchHasChanges(buildStatePatch(lastSyncedState, state));
    } catch (error) {
      console.warn("No se pudo evaluar cambios locales pendientes:", error.message);
      return false;
    }
  }

  async function cloudPull(manual, isLogin) {
    const config = getCloudSyncConfig();
    if (!canReadCloudState()) {
      if (manual) alert("El rol Cliente no descarga el estado completo. La informacion se actualiza por las pantallas permitidas.");
      return;
    }
    if (!cloudSyncReady(config)) {
      if (manual) alert("Configure la URL y el token del backend en este panel.");
      return;
    }
    try {
      const response = await cloudRequest(config, "/state", { method: "GET" });
      if (response.status === 404) {
        if (manual) alert("Todavia no hay datos en la nube. Use Subir datos ahora desde el dispositivo principal.");
        return;
      }
      if (!response.ok) throw new Error("HTTP " + response.status + (await readCloudErrorDetail(response)));
      const payload = await response.json();
      if (!payload || typeof payload.data !== "object") throw new Error("respuesta inválida");
      const remoteUpdated = String(payload.updatedAt || "");
      if (!manual && !isLogin) {
        if (config.lastSync && remoteUpdated && remoteUpdated <= config.lastSync) return;
        if (!config.lastSync) return;
      }
      if (!manual) {
        const active = document.activeElement;
        const typing = active && ["INPUT", "TEXTAREA", "SELECT"].includes(active.tagName);
        if (typing || ui.modal || cloudPushTimer) return;
      }
      const localUnsyncedChanges = hasLocalUnsyncedPatchChanges();
      if (!manual && !isLogin && localUnsyncedChanges) {
        const msg = "Descarga automatica omitida: hay cambios locales pendientes. Primero se intentara subir o fusionar esos cambios.";
        ui.syncStatus = "Cambios pendientes por sincronizar";
        ui.syncWarning = msg;
        schedulePatchFlush(1200);
        return;
      }
      if (!manual && looksLikeSeedState(payload.data) && localStateIsRicherThanRemote(state, payload.data)) {
        console.warn("Sincronización: el servidor tiene datos de ejemplo/vacío; se conservan los datos locales.");
        return;
      }
      // Safety check: prevent silent overwrite when local state has more operational data
      if (!localUnsyncedChanges && localStateIsNewerOrRicher(state, payload.data)) {
        const local = stateOperationalCounts(state);
        const remote = stateOperationalCounts(payload.data);
        const details = Object.keys(local)
          .filter((k) => local[k] !== remote[k])
          .map((k) => `${k}: local ${local[k]} vs nube ${remote[k]}`)
          .join(", ");
        const msg = `Sincronización bloqueada: los datos locales tienen más información (${details}). Use 'Subir datos ahora' para enviarlos, o 'Descargar datos ahora' si está seguro de reemplazarlos.`;
        ui.syncWarning = msg;
        if (!manual) {
          console.warn(msg);
          config.lastError = msg;
          saveCloudSyncConfig(config);
          render();
          return;
        }
        if (!confirm(`ADVERTENCIA: los datos locales tienen más información que la nube (${details}). Reemplazar los datos locales con la nube?`)) return;
      } else {
        ui.syncWarning = "";
      }
      backupLocalState("antes de descarga de nube");
      const backupIndexBeforeOverwrite = 0; // backupLocalState inserts at index 0
      const localOrdersBefore = Array.isArray(state.orders) ? state.orders.length : 0;
      const remoteState = normalizeLoadedState({ ...seedState(), ...payload.data }, seedState());
      state = localUnsyncedChanges
        ? normalizeLoadedState({ ...seedState(), ...mergeCloudStates(remoteState, state) }, seedState())
        : remoteState;
      writeLocalStateSnapshot(state, "No se pudo guardar la descarga de nube en localStorage.");
      config.lastSync = remoteUpdated || new Date().toISOString();
      config.lastError = "";
      saveCloudSyncConfig(config);
      lastSyncedState = localUnsyncedChanges ? cloneSyncState(remoteState) : cloneSyncState(state);
      let clearedQueueCount = 0;
      let requeuedMergedPatch = false;
      if (localUnsyncedChanges) {
        clearedQueueCount = loadPatchQueue().length;
        savePatchQueue([]);
        pendingPatchBaseState = lastSyncedState;
        pendingPatchBaseUpdatedAt = config.lastSync;
        requeuedMergedPatch = queueCurrentStatePatch();
        if (requeuedMergedPatch) schedulePatchFlush(1200);
        ui.syncWarning = "Se fusionaron datos de nube con cambios locales pendientes. Los cambios locales quedaron listos para subir.";
      } else {
        clearedQueueCount = clearPatchQueueAfterCloudPull("Datos descargados; cola pendiente anterior limpiada");
      }
      if (!requeuedMergedPatch) {
        pendingPatchBaseState = null;
        pendingPatchBaseUpdatedAt = "";
      }
      currentUser = loadCurrentUser();
      const remoteOrdersAfter = Array.isArray(state.orders) ? state.orders.length : 0;
      if (remoteOrdersAfter < localOrdersBefore) {
        ui.lastOverwrite = { at: Date.now(), backupIndex: backupIndexBeforeOverwrite, ordersBefore: localOrdersBefore, ordersAfter: remoteOrdersAfter };
      } else {
        ui.lastOverwrite = null;
      }
      render();
      if (manual) {
        if (localUnsyncedChanges) {
          alert(requeuedMergedPatch
            ? "Datos descargados y fusionados con cambios locales. Los cambios locales quedaron pendientes para subir sin pisar la nube."
            : "Datos descargados y fusionados correctamente.");
        } else {
          alert(clearedQueueCount ? `Datos descargados de la nube correctamente. Se limpiaron ${clearedQueueCount} cambio(s) pendiente(s) anteriores porque pertenecian a una version vieja del servidor.` : "Datos descargados de la nube correctamente.");
        }
      }
    } catch (error) {
      const errorConfig = getCloudSyncConfig();
      errorConfig.lastError = "Descarga fallida " + formatTimestampShort(new Date().toISOString()) + ": " + error.message;
      saveCloudSyncConfig(errorConfig);
      console.warn("Sincronización: " + error.message);
      if (manual) alert("No se pudo descargar de la nube: " + error.message);
    }
  }

  async function cloudTest() {
    const config = getCloudSyncConfig();
    if (!cloudSyncReady(config)) return alert("Complete la URL y el token, y presione Guardar configuración.");
    try {
      const health = await fetch(cloudBaseUrl(config) + "/health");
      if (!health.ok) throw new Error("el backend no responde (HTTP " + health.status + ")");
      if (config.username) await cloudLogin(config);
      const stateResponse = await cloudRequest(config, "/state", { method: "GET" });
      if (stateResponse.status === 401) throw new Error(config.username ? "usuario o contraseña incorrectos" : "token incorrecto (revise que el secreto API_TOKEN del Worker sea igual al token pegado aca)");
      if (stateResponse.status === 403) throw new Error("ese usuario no tiene permisos de sincronización (use gerente, admin o empleado)");
      if (!stateResponse.ok && stateResponse.status !== 404) throw new Error("el backend respondio HTTP " + stateResponse.status + (await readCloudErrorDetail(stateResponse)));
      alert("Conexión correcta. " + (stateResponse.status === 404 ? "La nube todavía no tiene datos: use Subir datos ahora." : "Hay datos guardados en la nube."));
    } catch (error) {
      alert("Fallo la prueba de conexión: " + error.message);
    }
  }

  function loadCurrentUser() {
    try {
      const id = localStorage.getItem(USER_KEY);
      if (!id) return null;
      return state.users.find((user) => user.id === id) || null;
    } catch {
      return null;
    }
  }

  function setCurrentUser(user) {
    currentUser = user;
    if (user) localStorage.setItem(USER_KEY, user.id);
    else localStorage.removeItem(USER_KEY);
  }

  // Si el sistema quedo abierto de un dia para el otro, al cambiar de dia se reajustan a hoy
  // los filtros de fecha operativos (los que siguen "hoy"). No toca Saldos (Desde) ni Facturacion.
  function realignDatesToTodayOnDayChange() {
    const t = todayISO();
    if (ui.lastActiveDay === t) return;
    ui.ordersFrom = t; ui.ordersTo = t;
    ui.providerFrom = t; ui.providerTo = t;
    ui.remitosFrom = t; ui.remitosTo = t;
    ui.unitsDate = t;
    ui.vehicleDate = t;
    ui.balanceTo = t;            // Saldos: solo el "Hasta"; el "Desde" queda como estaba.
    ui.performanceFrom = t; ui.performanceTo = t; ui.performanceDate = t;
    ui.historyFrom = t; ui.historyTo = t;          // Historiales / analisis de compra
    ui.billingTo = t;            // Facturacion: solo el "Hasta"; el "Desde" queda como estaba.
    ui.lastActiveDay = t;
  }

  function render() {
    afterRender = [];
    realignDatesToTodayOnDayChange();
    const app = document.getElementById("app");
    if (!currentUser) {
      app.innerHTML = renderLogin();
      bindLogin();
      return;
    }

    const route = getRoute();
    if (!canAccess(route.base)) {
      navigate(roleHome(), true);
      return;
    }

    const page = renderRoute(route);
    app.innerHTML = `
      <div id="offline-banner" class="offline-banner" style="display:${typeof navigator !== "undefined" && navigator.onLine === false ? "block" : "none"}">Sin conexión a internet: los cambios se guardan en este dispositivo y se sincronizarán al volver la conexión.</div>
      ${(() => { const n = pendingSyncCount(); return n ? `<div class="offline-banner" style="display:block;background:#b45309;color:#fff">\u26A0 ${n} cambio(s) sin enviar al sistema. Se enviarán al reconectar; no cierres el sistema con internet apagado.</div>` : ""; })()}
      <div class="app-shell">
        ${renderSidebar(route.base)}
        <div class="sidebar-overlay" aria-hidden="true"></div>
        <main class="main">
          ${renderTopbar()}
          ${page}
        </main>
      </div>
      ${renderModal()}
    `;
    bindCommon();
    afterRender.forEach((fn) => fn());
    maybeForcePasswordChange();
  }

  const DEFAULT_PASSWORDS = ["gerente123", "admin123", "empleado123", "cliente123"];

  function maybeForcePasswordChange() {
    if (!currentUser || ui.modal) return;
    if (!["manager", "admin", "employee", "contador"].includes(currentUser.role)) return;
    const stateUser = state.users.find((item) => item.id === currentUser.id);
    if (!stateUser || !DEFAULT_PASSWORDS.includes(String(stateUser.password || ""))) return;
    if (window.__pcForcePwdOpen) return;
    window.__pcForcePwdOpen = true;
    showModal(
      "Cambie su contraseña",
      `
      <div class="alert" style="margin-bottom:12px">Su cuenta todavía usa la contraseña por defecto. Por seguridad debe crear una nueva antes de continuar.</div>
      <form id="force-pwd-form" class="grid">
        <div class="field"><label>Nueva contraseña (mínimo 8 caracteres)</label><input id="force-pwd-1" type="password" autocomplete="new-password" /></div>
        <div class="field"><label>Repetir contraseña</label><input id="force-pwd-2" type="password" autocomplete="new-password" /></div>
      </form>
      `,
      () => {
        const saveButton = document.getElementById("modal-save");
        if (saveButton) saveButton.addEventListener("click", () => {
          const p1 = document.getElementById("force-pwd-1").value;
          const p2 = document.getElementById("force-pwd-2").value;
          if (p1.length < 8) return alert("La contraseña debe tener al menos 8 caracteres.");
          if (DEFAULT_PASSWORDS.includes(p1)) return alert("Elija una contraseña distinta a las contraseñas por defecto.");
          if (p1 !== p2) return alert("Las contraseñas no coinciden.");
          const stateUser = state.users.find((item) => item.id === currentUser.id);
          if (stateUser) stateUser.password = p1;
          const config = getCloudSyncConfig();
          if (config.username && config.username === currentUser.username) {
            config.password = p1;
            config.jwt = "";
            saveCloudSyncConfig(config);
          }
          saveState();
          window.__pcForcePwdOpen = false;
          closeModal();
          alert("Contraseña actualizada correctamente.");
        });
      },
      { saveLabel: "Guardar contraseña", cancelLabel: "Más tarde" }
    );
  }

  function renderLogin() {
    const hash = String(location.hash || "");
    if (hash.startsWith("#/restablecer/")) {
      ui.loginView = "reset";
      ui.resetToken = decodeURIComponent(hash.replace("#/restablecer/", ""));
    }
    const view = ui.loginView || "login";
    let body = "";
    if (view === "register") {
      body = `
        <h2 style="margin:0 0 8px;font-size:18px">Registro de cliente</h2>
        <div class="alert" style="margin-bottom:12px;display:none" id="reg-invoice-alert">Con Factura se cobrara el IVA</div>
        <form id="register-form" class="form-grid register-grid">
          <div class="field span-2"><label>Nombre de usuario *</label><input id="reg-username" autocomplete="off" /></div>
          <div class="field span-2"><label>Contrasena * (mínimo 6)</label><input id="reg-password" type="password" autocomplete="new-password" /></div>
          <div class="field span-2"><label>Nombre del local *</label><input id="reg-local" /></div>
          <div class="field span-2"><label>Direccion *</label><input id="reg-address" /></div>
          <div class="field span-2"><label id="reg-cuit-label">CUIT</label><input id="reg-cuit" placeholder="30-12345678-9" /></div>
          <div class="field span-2"><label>Correo electrónico *</label><input id="reg-email" type="email" /></div>
          <div class="field"><label>Apertura del local *</label><input id="reg-opening" type="time" /></div>
          <div class="field"><label>Horario máximo de entrega *</label><input id="reg-delivery" type="time" /></div>
          <div class="field"><label>Telefono *</label><input id="reg-phone" inputmode="tel" /></div>
          <div class="field"><label>Zona *</label><input id="reg-zone" /></div>
          <div class="field span-2"><label>Facturacion *</label><select id="reg-invoice"><option value="Sin Factura">Sin factura</option><option value="Factura A">Factura A</option><option value="Factura B">Factura B</option></select></div>
          <div class="field span-2"><label>Correo de facturacion (opcional)</label><input id="reg-billing-email" type="email" /></div>
          <div class="field span-4"><label>Nota (opcional)</label><textarea id="reg-notes"></textarea></div>
          <div class="field span-4"><button class="btn primary full" type="submit">Registrarme</button></div>
        </form>
        <button class="btn ghost full" type="button" id="back-to-login" style="margin-top:10px">Volver al ingreso</button>
      `;
    } else if (view === "registered") {
      body = `
        <div class="alert" style="margin-bottom:14px">Su cuenta queda pendiente de aprobación, por favor comunicarse con administración para empezar a trabajar con nosotros.</div>
        <a class="btn full whatsapp-btn" href="${WHATSAPP_REGISTER_LINK}" target="_blank" rel="noopener">${WHATSAPP_SVG}&nbsp;Escribirnos por WhatsApp</a>
        <button class="btn ghost full" type="button" id="back-to-login" style="margin-top:10px">Volver al ingreso</button>
      `;
    } else if (view === "recover") {
      body = `
        <h2 style="margin:0 0 8px;font-size:18px">Recuperar contraseña</h2>
        <p class="muted" style="margin:0 0 12px">Le enviaremos un correo con un enlace para crear una contraseña nueva.</p>
        <form id="recover-form" class="grid">
          <div class="field"><label>Usuario o correo electrónico</label><input id="recover-identifier" autocomplete="username" /></div>
          <button class="btn primary full" type="submit">Enviar correo de recuperacion</button>
        </form>
        <button class="btn ghost full" type="button" id="back-to-login" style="margin-top:10px">Volver al ingreso</button>
      `;
    } else if (view === "reset") {
      body = `
        <h2 style="margin:0 0 8px;font-size:18px">Crear nueva contraseña</h2>
        <form id="reset-form" class="grid">
          <div class="field"><label>Nueva contraseña (mínimo 6)</label><input id="reset-password" type="password" autocomplete="new-password" /></div>
          <div class="field"><label>Repetir contraseña</label><input id="reset-password2" type="password" autocomplete="new-password" /></div>
          <button class="btn primary full" type="submit">Guardar contraseña</button>
        </form>
        <button class="btn ghost full" type="button" id="back-to-login" style="margin-top:10px">Volver al ingreso</button>
      `;
    } else {
      body = `
        <form id="login-form" class="grid">
          <div class="field">
            <label>Usuario</label>
            <input id="login-username" autocomplete="username" placeholder="usuario o correo electrónico" />
          </div>
          <div class="field">
            <label>Contrasena</label>
            <div class="password-field"><input id="login-password" type="password" autocomplete="current-password" placeholder="Ingrese su contraseña" /><button class="password-toggle" type="button" id="toggle-login-password" aria-label="Ver contraseña" title="Ver contraseña">&#128065;</button></div>
          </div>
          <button class="btn primary full" type="submit">Ingresar</button>
        </form>
        <div class="login-actions">
          <button class="btn ghost full" type="button" id="open-register">Registrarme como cliente</button>
          <button class="btn ghost full" type="button" id="open-recover">Me olvide la contraseña</button>
        </div>
      `;
    }
    return `
      <section class="login-screen">
        <div class="login-panel ${view === "register" ? "login-panel-wide" : ""}">
          <h1 class="login-title">${BUSINESS_NAME}</h1>
          <p class="login-subtitle">Insumos Frescos para Gastronomicos</p>
          ${body}
          <img class="login-logo" src="./assets/logo.png" alt="Pare Carrito SAS" />
        </div>
      </section>
    `;
  }

  async function findServerBase() {
    const config = getCloudSyncConfig();
    const candidates = [];
    if (config.url) candidates.push(cloudBaseUrl(config));
    candidates.push("/api");
    for (const base of candidates) {
      try {
        const health = await fetch(base + "/health");
        if (!health.ok) continue;
        const body = await health.json().catch(() => null);
        if (body && body.ok === true) return base;
      } catch {}
    }
    return null;
  }

  function bindLoginExtras() {
    const openRegister = document.getElementById("open-register");
    if (openRegister) openRegister.addEventListener("click", () => {
      ui.loginView = "register";
      render();
    });
    const openRecover = document.getElementById("open-recover");
    if (openRecover) openRecover.addEventListener("click", () => {
      ui.loginView = "recover";
      render();
    });
    const backButton = document.getElementById("back-to-login");
    if (backButton) backButton.addEventListener("click", () => {
      ui.loginView = "login";
      ui.resetToken = "";
      if (String(location.hash || "").startsWith("#/restablecer/")) location.hash = "";
      render();
    });
    const regInvoice = document.getElementById("reg-invoice");
    if (regInvoice) {
      regInvoice.addEventListener("change", () => {
        const needsInvoice = regInvoice.value !== "Sin Factura";
        const invoiceAlert = document.getElementById("reg-invoice-alert");
        if (invoiceAlert) invoiceAlert.style.display = needsInvoice ? "block" : "none";
        const cuitLabel = document.getElementById("reg-cuit-label");
        if (cuitLabel) cuitLabel.textContent = needsInvoice ? "CUIT *" : "CUIT";
      });
      regInvoice.dispatchEvent(new Event("change"));
    }
    const registerForm = document.getElementById("register-form");
    if (registerForm) registerForm.addEventListener("submit", async (event) => {
      event.preventDefault();
      const get = (id) => document.getElementById(id).value.trim();
      const payload = {
        username: get("reg-username").toLowerCase(),
        password: document.getElementById("reg-password").value,
        localName: get("reg-local"),
        address: get("reg-address"),
        cuit: get("reg-cuit"),
        email: get("reg-email"),
        openingTime: get("reg-opening"),
        maxDeliveryTime: get("reg-delivery"),
        phone: get("reg-phone"),
        zone: get("reg-zone"),
        invoiceType: document.getElementById("reg-invoice").value,
        billingEmail: get("reg-billing-email"),
        notes: get("reg-notes")
      };
      const needsInvoice = payload.invoiceType !== "Sin Factura";
      const requiredOk = payload.username && payload.password && payload.localName && payload.address && (!needsInvoice || payload.cuit) && payload.email && payload.openingTime && payload.maxDeliveryTime && payload.phone && payload.zone;
      if (!requiredOk) return alert("Complete todos los campos obligatorios (*).");
      if (payload.password.length < 6) return alert("La contraseña debe tener al menos 6 caracteres.");
      const base = await findServerBase();
      if (!base) return alert("El registro en linea esta disponible solo con el servidor del negocio. Comuniquese con administración.");
      try {
        const response = await fetch(base + "/auth/register", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify(payload)
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok) return alert(result.error || "No se pudo completar el registro (HTTP " + response.status + ").");
        ui.loginView = "registered";
        render();
      } catch (error) {
        alert("No se pudo completar el registro: " + error.message);
      }
    });
    const recoverForm = document.getElementById("recover-form");
    if (recoverForm) recoverForm.addEventListener("submit", async (event) => {
      event.preventDefault();
      const identifier = document.getElementById("recover-identifier").value.trim();
      if (!identifier) return alert("Indique su usuario o correo electrónico.");
      const base = await findServerBase();
      if (!base) return alert("La recuperacion en linea esta disponible solo con el servidor del negocio. Comuniquese con administración.");
      try {
        const response = await fetch(base + "/auth/recover", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ usernameOrEmail: identifier })
        });
        const result = await response.json().catch(() => ({}));
        alert(result.message || "Si el usuario existe y tiene correo registrado, le enviamos las instrucciones.");
        ui.loginView = "login";
        render();
      } catch (error) {
        alert("No se pudo enviar el correo: " + error.message);
      }
    });
    const resetForm = document.getElementById("reset-form");
    if (resetForm) resetForm.addEventListener("submit", async (event) => {
      event.preventDefault();
      const password = document.getElementById("reset-password").value;
      const password2 = document.getElementById("reset-password2").value;
      if (password.length < 6) return alert("La contraseña debe tener al menos 6 caracteres.");
      if (password !== password2) return alert("Las contraseñas no coinciden.");
      const base = await findServerBase();
      if (!base) return alert("No se pudo contactar al servidor del negocio.");
      try {
        const response = await fetch(base + "/auth/reset", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ token: ui.resetToken, password })
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok) return alert(result.error || "No se pudo cambiar la contraseña.");
        alert("Contrasena actualizada. Ya puede ingresar con la nueva contraseña.");
        ui.loginView = "login";
        ui.resetToken = "";
        location.hash = "";
        render();
      } catch (error) {
        alert("No se pudo cambiar la contraseña: " + error.message);
      }
    });
  }

  function bindLogin() {
    bindLoginExtras();
    const loginForm = document.getElementById("login-form");
    if (!loginForm) return;
    const toggleLoginPwd = document.getElementById("toggle-login-password");
    if (toggleLoginPwd) toggleLoginPwd.addEventListener("click", () => {
      const inp = document.getElementById("login-password");
      if (inp) inp.type = inp.type === "password" ? "text" : "password";
    });
    loginForm.addEventListener("submit", async (event) => {
      event.preventDefault();
      const username = document.getElementById("login-username").value.trim().toLowerCase();
      const password = document.getElementById("login-password").value;
      const submitButton = event.target.querySelector("button[type=submit]");
      if (submitButton) submitButton.disabled = true;
      try {
        // 1) Si hay un servidor propio disponible (mismo dominio /api o el
        //    configurado en Backup), autenticar ahi: cero configuracion por dispositivo.
        const serverResult = await tryServerLogin(username, password);
        if (serverResult && serverResult.payload) {
          const config = getCloudSyncConfig();
          config.url = serverResult.base;
          config.username = username;
          config.password = password;
          config.jwt = serverResult.payload.token;
          if (config.auto !== false) config.auto = true;
          saveCloudSyncConfig(config);
          if (["manager", "admin", "employee", "contador"].includes(serverResult.payload.role)) {
            await cloudPull(false, true);
          }
          if (["manager", "admin", "employee", "contador"].includes(serverResult.payload.role)) {
            startCloudAutoSync();
          }
          let user = state.users.find((item) => item.isActive !== false && (item.username.toLowerCase() === username || String(item.email || "").toLowerCase() === username));
          if (!user) {
            user = { id: "USR-REMOTE-" + Date.now(), username, name: serverResult.payload.name || username, role: serverResult.payload.role, password, isActive: true };
            state.users.push(user);
            writeLocalStateSnapshot(state, "No se pudo guardar el usuario remoto en localStorage.");
          }
          setCurrentUser(user);
          navigate(roleHome(), true);
          render();
          return;
        }
        if (serverResult && serverResult.failed && serverResult.status === 401) {
          alert("Usuario o contraseña incorrectos.");
          return;
        }
        // 2) Sin servidor: ingreso local como siempre.
        const user = state.users.find((item) => item.isActive !== false && (item.username.toLowerCase() === username || String(item.email || "").toLowerCase() === username) && item.password === password);
        if (!user) {
          alert("Usuario o contraseña incorrectos.");
          return;
        }
        setCurrentUser(user);
        navigate(roleHome(), true);
        render();
      } finally {
        if (submitButton) submitButton.disabled = false;
      }
    });
  }

  async function tryServerLogin(username, password) {
    const config = getCloudSyncConfig();
    const candidates = [];
    if (config.url && config.username) candidates.push(cloudBaseUrl(config));
    candidates.push("/api");
    for (const base of candidates) {
      try {
        const health = await fetch(base + "/health");
        if (!health.ok) continue;
        const healthBody = await health.json().catch(() => null);
        if (!healthBody || healthBody.ok !== true) continue;
        const response = await fetch(base + "/auth/login", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ username, password })
        });
        if (response.status === 401) return { failed: true, status: 401 };
        if (!response.ok) continue;
        const payload = await response.json();
        if (!payload || !payload.token) continue;
        return { payload, base };
      } catch {
        continue;
      }
    }
    return null;
  }

  function renderSidebar(activeRoute) {
    const items = getOrderedMenuItems().filter((item) => pageVisibleForRole(item, currentUser.role));
    return `
      <aside class="sidebar">
        <div class="brand">
          <div class="brand-title">${BUSINESS_NAME}</div>
        </div>
        <div class="user-box">
          <strong>${escapeHtml(currentUser.name)}</strong>
          <span class="role-badge">${roleLabel(currentUser.role)}</span>
        </div>
        <nav class="nav" aria-label="Navegacion principal">
          ${items.map((item) => {
            const label = menuLabel(item);
            return `
            <button class="${activeRoute === item.id ? "active" : ""}" data-route="${item.id}" title="${escapeHtml(label)}">
              <span class="nav-icon">${menuIcon(item.id) || escapeHtml(item.icon)}</span>
              <span>${escapeHtml(label)}</span>
            </button>
          `;
          }).join("")}
        </nav>
        <div class="sidebar-footer">
          <button class="btn ghost full" data-logout>Salir de la cuenta</button>
        </div>
      </aside>
    `;
  }

